        assertEquals(Instant.parse("2026-03-16T04:00:00Z"), dueAt);
    }

    @Test
    void rejectsNegativePaymentTerms() {
        assertThrows(
                IllegalArgumentException.class,
                () -> calculator.dueAt(
                        LocalDate.of(2026, 2, 2),
                        -1,
                        BillingTestFixture.newYorkBillingZone()));
    }

    /**
     * The autumn transition is the same defect in the opposite direction: a wall-clock
     * duration of 30 x 24h lands an hour early, so the invoice falls due at 23:00 on the
     * day <em>before</em> the intended date. Covering only the spring transition would
     * let a fix that merely subtracts an hour pass unnoticed.
     */
    @Test
    void paymentTermKeepsLocalMidnightAcrossFallBackChange() {
        Instant dueAt = calculator.dueAt(
                LocalDate.of(2026, 10, 15),
                30,
                BillingTestFixture.newYorkBillingZone());

        assertEquals(Instant.parse("2026-11-14T05:00:00Z"), dueAt);
    }

    /** A zero term is the smallest accepted value and must not shift off the issue date. */
    @Test
    void zeroTermIsDueAtLocalMidnightOnTheIssueDate() {
        Instant dueAt = calculator.dueAt(
                LocalDate.of(2026, 2, 2),
                0,
                BillingTestFixture.newYorkBillingZone());

        assertEquals(Instant.parse("2026-02-02T05:00:00Z"), dueAt);
    }

    /** Guards the {@code termDays < 0} boundary, including that it is not overflow-sensitive. */
    @ParameterizedTest
    @ValueSource(ints = {-1, -2, -30, Integer.MIN_VALUE})
    void rejectsEveryNegativePaymentTerm(int termDays) {
        assertThrows(
                IllegalArgumentException.class,
                () -> calculator.dueAt(
                        LocalDate.of(2026, 2, 2),
                        termDays,
                        BillingTestFixture.newYorkBillingZone()));
    }

    /**
     * The invariant the fix rests on: whatever the term, the due instant is local midnight
     * on {@code issueDate.plusDays(termDays)} in the billing zone. Swept across both 2026
     * transitions so no window length can silently drift.
     */
    @ParameterizedTest(name = "issued {0} + {1}d")
    @MethodSource("termsSpanningBothDaylightSavingTransitions")
    void dueInstantIsAlwaysLocalMidnightOnTheDueDate(LocalDate issueDate, int termDays) {
        ZoneId zone = BillingTestFixture.newYorkBillingZone();

        ZonedDateTime due = calculator.dueAt(issueDate, termDays, zone).atZone(zone);

        assertEquals(issueDate.plusDays(termDays), due.toLocalDate(),
                () -> "due calendar date drifted for " + issueDate + " + " + termDays + "d");
        assertEquals(LocalTime.MIDNIGHT, due.toLocalTime(),
                () -> "due local time drifted for " + issueDate + " + " + termDays + "d");
    }

    private static Stream<Arguments> termsSpanningBothDaylightSavingTransitions() {
        return List.of(
                        LocalDate.of(2026, 3, 8),   // spring forward: 02:00 -> 03:00
                        LocalDate.of(2026, 11, 1))  // fall back:      02:00 -> 01:00
                .stream()
                .flatMap(transition -> IntStream.rangeClosed(-10, 10).mapToObj(transition::plusDays))
                .flatMap(issueDate -> Stream.of(0, 1, 30)
                        .map(termDays -> Arguments.of(issueDate, termDays)));
    }
}

